patch:
diff --git a/recreate/check-use-strict.js b/recreate/check-use-strict.js
new file mode 100644
index 0000000..a81e297
--- /dev/null
+++ b/recreate/check-use-strict.js
@@ -0,0 +1,32 @@
+"use strict";
+
+/*
+ * Check: `no-unused-expressions` must not report `'use strict'` directives,
+ * including with `languageOptions.ecmaVersion: 3` (core-js lints packages/core-js/** that way).
+ * Exits non-zero while the bug is present, zero once it is fixed.
+ *
+ * Usage: node recreate/check-use-strict.js [ecmaVersion=3]
+ * Set ESLINT_DIR to test another installed eslint (e.g. a published release).
+ */
+
+const path = require("node:path");
+const { Linter } = require(process.env.ESLINT_DIR || path.join(__dirname, "..", "lib", "api"));
+
+const ecmaVersion = process.argv[2] === "latest" ? "latest" : Number(process.argv[2] || 3);
+const code = "'use strict';\nfunction f() {\n  'use strict';\n}\n";
+
+const messages = new Linter().verify(code, [
+	{
+		languageOptions: { ecmaVersion, sourceType: "script" },
+		rules: { "no-unused-expressions": "error" },
+	},
+]);
+
+if (messages.length) {
+	console.error(`FAIL (ecmaVersion ${ecmaVersion}): expected no problems, got ${messages.length}:`);
+	for (const m of messages) {
+		console.error(`  ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+	}
+	process.exit(1);
+}
+console.log(`OK (ecmaVersion ${ecmaVersion}): no problems reported`);
